def test_scenario_36_sheet_final_update_failure_after_verified_publish(self, sample_github_headers, sample_7_draft_rows, mock_db, tmp_path):
        ws = MockWorksheet(sample_github_headers, sample_7_draft_rows)
        for r in ws.data:
